:root {
  --color-primary: #8b4a6a;
  --color-primary-dark: #6b3a52;
  --color-primary-light: #d4a5c4;
  --color-accent: #e8b4d4;
  --color-accent-on-dark: #f0d9e8;
  --color-text: #2c2c2c;
  --color-text-light: #5a5a5a;
  --color-bg: #faf8fc;
  --color-bg-light: #f5f3f8;
  --color-border: #e0d5e8;
  --color-success: #5a9b6f;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --radius: 8px;
  --shadow-sm: 0 2px 8px rgba(107, 58, 82, 0.1);
  --shadow-md: 0 4px 16px rgba(107, 58, 82, 0.15);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header & Logo */
.header {
  background-color: white;
  border-bottom: 2px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.logo {
  font-family: var(--font-serif);
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1.25rem, 5vw, 1.75rem);
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 1px solid var(--color-primary-dark);
  display: inline-block;
  padding-bottom: 0.3rem;
  transition: color 0.3s ease;
}

.logo:hover,
.logo:focus {
  color: var(--color-primary);
  outline: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  font-weight: 600;
  line-height: 1.3;
}

h1 {
  font-size: 3rem;
  margin-bottom: var(--spacing-lg);
}

h2 {
  font-size: 2rem;
  margin-bottom: var(--spacing-md);
}

h3 {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-sm);
}

p {
  margin-bottom: var(--spacing-sm);
}

a:not(.logo) {
  color: var(--color-primary-dark);
  text-decoration: underline;
  transition: color 0.2s ease;
}

a:not(.logo):hover,
a:not(.logo):focus {
  color: var(--color-primary);
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Buttons */
button,
.btn {
  display: inline-block;
  padding: 0.75rem 2rem;
  min-height: 44px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.3s ease;
  text-align: center;
  vertical-align: middle;
}

button:focus,
.btn:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: white;
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(2px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary-dark);
  border: 2px solid var(--color-primary-dark);
}

.btn-secondary:hover {
  background-color: var(--color-bg-light);
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 500;
  color: var(--color-text);
}

input,
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background-color: white;
  color: var(--color-text);
  transition: border-color 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(107, 58, 82, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

/* Cards */
.card {
  background-color: white;
  border-radius: var(--radius);
  padding: var(--spacing-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-md);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

/* Footer */
.footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0 var(--spacing-lg);
  margin-top: var(--spacing-xl);
  text-align: center;
}

.footer p {
  margin-bottom: var(--spacing-xs);
  font-size: 0.95rem;
}

.footer a {
  color: var(--color-accent-on-dark);
  text-decoration: underline;
}

.footer a:hover,
.footer a:focus {
  color: white;
}

/* Mobile (max-width: 600px) */
@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  h1 {
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .grid-2 {
    grid-template-columns: 1fr;
  }

  button,
  .btn {
    width: 100%;
    min-height: 48px;
  }

  form {
    gap: var(--spacing-sm);
  }
}

/* Desktop (min-width: 601px) */
@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .grid {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }

  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

