  .index-testimonials,
  .index-booking {
    padding: var(--spacing-lg) 0;
  }

  .index-services h2,
  .index-why-us h2,
  .index-testimonials h2,
  .index-booking h2 {
    margin-bottom: var(--spacing-lg);
