    grid-template-columns: 1fr;
    gap: var(--spacing-sm);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-services,
  .index-why-us,
  .index-testimonials,
  .index-booking {
    padding: var(--spacing-xl) var(--spacing-lg);
  }
}

