  color: var(--color-primary-dark);
  margin-left: 0.25rem;
}

.index-booking-info {
  max-width: 700px;
  margin: var(--spacing-lg) auto 0;
  text-align: center;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero h1 {
    font-size: 2rem;
  }

  .index-hero-tagline {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-md);
  }

  .index-hero-description {
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
  }

  .index-services,
  .index-why-us,
  .index-testimonials,
  .index-booking {
    padding: var(--spacing-lg) 0;
  }

  .index-services h2,
  .index-why-us h2,
  .index-testimonials h2,
  .index-booking h2 {
    margin-bottom: var(--spacing-lg);
  }

  .index-form-row {
    grid-template-columns: 1fr;
    gap: var(--spacing-sm);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-services,
  .index-why-us,
  .index-testimonials,
  .index-booking {
    padding: var(--spacing-xl) var(--spacing-lg);
  }
}
